/* From Uiverse.io by ashish-yadv - Tags: animation, loader, loading animation, bouncing animation, bounce animation */
.__UIV_SCOPE__ .loader {
  width: 60px;
  display: flex;
  justify-content: space-evenly;
}

.__UIV_SCOPE__ .ball {
  list-style: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: #fff;
}

.__UIV_SCOPE__ .ball:nth-child(1) {
  animation: bounce-1 2.1s ease-in-out infinite;
}

@keyframes bounce-1 {
  50% {
    transform: translateY(-18px);
  }
}

.__UIV_SCOPE__ .ball:nth-child(2) {
  animation: bounce-3 2.1s ease-in-out 0.3s infinite;
}

@keyframes bounce-2 {
  50% {
    transform: translateY(-18px);
  }
}

.__UIV_SCOPE__ .ball:nth-child(3) {
  animation: bounce-3 2.1s ease-in-out 0.6s infinite;
}

@keyframes bounce-3 {
  50% {
    transform: translateY(-18px);
  }
}
